244	) -> Result<axum::response::Response, (StatusCode, Json<ErrorBody>)> {
245	    let params = parse_snapshot_query(req.uri()).map_err(bad_request)?;
246	
247	    let store = state.store.lock().unwrap();
248	    let snapshot = store
249	        .snapshots
250	        .iter()
251	        .find(|s| s.version == params.version)
252	        .cloned()
253	        .ok_or_else(|| {
254	            (
255	                StatusCode::NOT_FOUND,
256	                Json(ErrorBody {
257	                    error: format!("版本 {} 不存在或尚未保存", params.version),
258	                    index: None,
259	                }),
260	            )
261	        })?;
262	
263	    match params.key {
264	        Some(key) => {
