impl Persist {
    /// 原子提交一个成功写入的批次。调用方必须保证只在整批校验通过后调用，
    /// 且磁盘提交成功后才修改内存状态（见 main.rs 中的处理函数）。
    pub(crate) fn commit_writes(
        &mut self,
        batch: &[(String, Map<String, Value>)],
    ) -> io::Result<()> {
        let seq = self.next_seq;
        let payload = EventPayload::Write {
            seq,
            records: batch
                .iter()
                .map(|(key, fields)| DiskRecord {
                    key: key.clone(),
